/**
 * A settings row: label and description beside one control (`design/components/settings-row.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/settings-row.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input } from '@angular/core'

import {
  MEMBER_PROVIDERS,
  SlotOutlet,
  SlotTemplate,
  derived,
  uniqueId,
  useMember,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/settings-row.module.css'
import type { SettingsRowGroupProps } from './SettingsRowGroup'

export type SettingsGroupProps = SettingsRowGroupProps

/** A settings row: label and description beside one control: the inputs it takes, by the React member's prop names. */
export interface SettingsRowProps {
  description?: string
  label: string
}

/** A settings row: label and description beside one control. */
@Component({
  selector: 'pm-settings-row',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [SlotOutlet, SlotTemplate],
  // prettier-ignore
  template: `<ng-template pmSlot="control" [pmSlotOf]="$"><ng-content select="[slot=control]" /></ng-template>
<div
[attr.class]="e1()"
data-member="settings-row"
><div
[attr.class]="e2()"
><span
[attr.class]="e3()"
[attr.id]="e4()"
>{{ e5() }}</span>
@if (e6()) {<span
[attr.class]="e7()"
[attr.id]="e8()"
>{{ e9() }}</span>}</div>
<div
[attr.class]="e10()"
><ng-container [pmSlotOutlet]="'control'" [pmSlotOf]="$" /></div></div>`,
})
export class SettingsRow {
  readonly description = input<SettingsRowProps['description']>(undefined)
  readonly label = input.required<SettingsRowProps['label']>()
  protected readonly $ = useMember({
    events: [],
    props: { description: () => this.description(), label: () => this.label() },
  })
  protected readonly $p = this.$.props
  protected readonly uid = uniqueId()
  protected readonly labelId = derived(() => `${this.uid}-label`)
  protected readonly descriptionId = derived(() => `${this.uid}-description`)

  constructor() {
    this.$.pass('control', () => ({
      'aria-labelledby': this.labelId.value,
      'aria-describedby': this.$p.description === undefined ? undefined : this.descriptionId.value,
    }))
  }

  protected e1() {
    return styles.row
  }

  protected e2() {
    return styles.text
  }

  protected e3() {
    return styles.label
  }

  protected e4() {
    return this.labelId.value
  }

  protected e5() {
    return this.$p.label
  }

  protected e6() {
    return this.$p.description !== undefined
  }

  protected e7() {
    if (!(this.$p.description !== undefined)) return undefined as never
    return styles.description
  }

  protected e8() {
    if (!(this.$p.description !== undefined)) return undefined as never
    return this.descriptionId.value
  }

  protected e9() {
    if (!(this.$p.description !== undefined)) return undefined as never
    return this.$p.description
  }

  protected e10() {
    return styles.control
  }
}
